using System;using System.Linq;using UnityEngine;
public static class InspectWeaponApex {
 static float Floor(SkinnedMeshRenderer r){var mesh=r.sharedMesh;var v=mesh.vertices;var w=mesh.boneWeights;var m=r.bones.Select((b,i)=>b.localToWorldMatrix*mesh.bindposes[i]).ToArray();float y=float.MaxValue;for(int i=0;i<v.Length;i++){var a=w[i];var p=m[a.boneIndex0].MultiplyPoint3x4(v[i])*a.weight0+m[a.boneIndex1].MultiplyPoint3x4(v[i])*a.weight1+m[a.boneIndex2].MultiplyPoint3x4(v[i])*a.weight2+m[a.boneIndex3].MultiplyPoint3x4(v[i])*a.weight3;y=Mathf.Min(y,p.y);}return y;}
 public static object Run(){var source=GameObject.Find("Attack 06 - Weapon_Combo_1");var temp=UnityEngine.Object.Instantiate(source);temp.hideFlags=HideFlags.HideAndDontSave;try{temp.transform.SetPositionAndRotation(Vector3.zero,Quaternion.identity);var a=temp.GetComponentInChildren<Animator>();var clip=a.runtimeAnimatorController.animationClips[0];a.enabled=false;var hip=a.GetComponentsInChildren<Transform>().First(t=>t.name=="Hips");var skin=temp.GetComponentInChildren<SkinnedMeshRenderer>();float maxHip=-999,maxFloor=-999,hipFrame=0,floorFrame=0;var samples=new System.Collections.Generic.List<object>();for(int i=0;i<=610;i++){float f=i/10f;clip.SampleAnimation(a.gameObject,f/30);float h=hip.position.y,y=Floor(skin);if(h>maxHip){maxHip=h;hipFrame=f;}if(y>maxFloor){maxFloor=y;floorFrame=f;}if(i%10==0&&f>=17&&f<=30)samples.Add(new{frame=f,hip=h,lowestBody=y});}return new{hipPeakFrame=hipFrame,bodyClearancePeakFrame=floorFrame,samples};}finally{UnityEngine.Object.DestroyImmediate(temp);}}
}
